function collect(
        uint256 pageId,
        uint8 grade,
        bytes32 fp,
        bytes32 nonce,
        uint256 deadline,
        bytes calldata sig
    ) external payable nonReentrant {
        require(live, "Not live");
        require(totalSupply() < COLLECTION_SIZE, "Complete");
        require(pageId >= 1 && pageId <= COLLECTION_SIZE, "Id");
        require(!pageMinted[pageId], "Minted");
        require(claimed[msg.sender] < WALLET_CAP, "Limit");
        require(grade >= GRADE_MIN && grade <= GRADE_MAX, "Grade");
        require(msg.value >= pricing[grade - 1], "Value");
        require(block.timestamp <= deadline, "Expired");
        require(!consumed[nonce], "Replay");
        require(!imprintUsed[fp], "Duplicate");

        if (grade == 1) {
            require(giftsClaimed < GIFT_CAP, "Gifts exhausted");
            require(!freeClaimed[msg.sender], "Gift used");
            giftsClaimed++;
            freeClaimed[msg.sender] = true;
        }

        bytes32 digest = keccak256(abi.encodePacked(
            msg.sender, pageId, grade, fp, nonce, deadline,
            block.chainid, address(this)
        ));
        require(
            digest.toEthSignedMessageHash().recover(sig) == authority,
            "Unauthorized"
        );

        uint256 id = pageId;
        // Deterministic seed based solely on pageId so book preview and on-chain render match
        uint256 dna = uint256(pageId * 1337 + 42);

        specimen[id] = dna;
        specimenGrade[id] = grade;
        imprint[id] = fp;
        imprintUsed[fp] = true;
        consumed[nonce] = true;
        claimed[msg.sender]++;
        pageMinted[pageId] = true;

        _safeMint(msg.sender, id);
    }

