    ) external payable {
        uint256 leftover = msg.value;
        uint256 spent = _checkNativeTxAndSend(
            _executor,
            _gasUnitsToFund,
            _prefund,
            targetedBlock
        );
        leftover = leftover - spent;
        block.coinbase.call{value: leftover}(new bytes(0));
    }

