        uint256 totalSupply   = pair.totalSupply();
        uint256 lpAtPair      = pair.balanceOf(PAIR);
        uint256 wethOut       = uint256(lpAtPair) * uint256(reserve1) / totalSupply;

        // Send WETH input to pair
